<?php require_once __DIR__.'/includes/auth.php';$page_title='Activity Logs';$rows=db()->query('SELECT * FROM activity_logs ORDER BY created_at DESC LIMIT 200')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-title"><div><h1>Activity Logs</h1><p>Admin audit trail and request history.</p></div></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>ACTION</th><th>ACTOR</th><th>IP</th><th>DATE</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['action'])?></td><td><?=e((string)$r['actor_id'])?></td><td><?=e($r['ip'])?></td><td><?=e(date('d M Y H:i',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php';?>
